// ============ MissAV 订阅源 · 公共 JS 库 ============
// 本库只放【不碰 java binding】的函数（jsLib 共享 scope 看不到 evalJS 注入的 java）：
//   ① sortUrl/searchUrl 的 {{MA_base()}} 内联调用
//   ② loginUrl 面板通过 this.source 读写线路变量
// 需要 java 的函数（发布页解析/测速）定义在 loginUrl 里（拼进 evalJS 能看到 java）。
// 线路变量唯一真身 = sourceVariable_<sourceUrl>（source.getVariable/setVariable 双环境共享）。

function MA_getData() {
  var d;
  try { d = this.source.getVariable(); } catch (e) { d = null; }
  if (d === null || d === undefined || d === '') return {};
  try { return JSON.parse(String(d)); } catch (e) { return {}; }
}

// 返回当前线路根（不含 /cn 等路径），给 {{MA_base()}} 用
function MA_base() {
  var d = MA_getData.call(this);
  var line = d.maLine;
  if (!line || String(line).indexOf('http') !== 0) line = 'https://www.missav9.net';
  return String(line).replace(/\/+$/, '');
}

// 面板写线路：双写 getVariable + source.put
function MA_writeLine(line) {
  var data = MA_getData.call(this);
  data.maLine = String(line).replace(/\/+$/, '');
  var s = JSON.stringify(data);
  try { this.source.setVariable(s); } catch (e) {}
  try { this.source.put('maLine', data.maLine); } catch (e) {}
  return data.maLine;
}

