// ============ MissAV 订阅源 · 登录/线路管理面板 ============
// loginUi 的 <js> 与 action 共用本文件（SourceLoginDialog 拼 "$loginJS\n$func"）
// 发布页输入框名：pub；认值从 result(Map) 读，默认 bbmap 门页。

function MA_toast(s, long) {
  try { if (long) java.longToast(s); else java.toast(s); } catch (e) { try { java.toast('' + s); } catch (e2) {} }
}
function MA_reUi() {
  try { java.reLoginView(); } catch (e) { try { java.reLoginView(false); } catch (e2) {} }
}

// ---- 发布页 → MissAV 线路池（必须定义在 loginUrl：jsLib scope 看不到 java binding）----
function MA_hdrPanel() {
  return '{"User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0.0.0 Safari/537.36","Accept-Language":"zh-CN,zh;q=0.9"}';
}
function MA_navLinesPanel() {
  var navs = ['https://x99dh.github.io/', 'https://x99dh.pages.dev/'];
  for (var n = 0; n < navs.length; n++) {
    try {
      var r = java.connect(navs[n], MA_hdrPanel(), 15000);
      var b = r.body() + '';
      var m = b.match(/encodedData\s*=\s*'([^']+)'/);
      if (!m) continue;
      var j = decodeURIComponent(java.base64Decode(m[1]));
      var arr = JSON.parse(j);
      for (var i = 0; i < arr.length; i++) {
        if (String(arr[i].name) === 'MissAV' && arr[i].urls) {
          var out = [];
          for (var k = 0; k < arr[i].urls.length; k++) {
            var u = String(arr[i].urls[k].url || '').replace(/\/+$/, '');
            if (u.indexOf('http') === 0 && out.indexOf(u) < 0) out.push(u);
          }
          if (out.length) return {lines: out, def: String(arr[i].url || out[0]), from: navs[n]};
        }
      }
    } catch (e) {}
  }
  return null;
}
function MA_fetchPub(pubUrl) {
  return MA_navLinesPanel();
}
function MA_lineList() {
  var d = MA_getData.call(this);
  var arr = d.maLines;
  if (!arr) return [];
  try { return JSON.parse(String(arr)); } catch (e) { return []; }
}
function MA_storeLines(lines) {
  var d = MA_getData.call(this);
  d.maLines = JSON.stringify(lines);
  var s = JSON.stringify(d);
  try { this.source.setVariable(s); } catch (e) {}
  return lines;
}
function MA_cur() {
  var d = MA_getData.call(this);
  return d.maLine || 'https://www.missav9.net';
}

// 面板按钮动态文本：显示 ⚡延时 + 域名 + 当前标记
function MA_lineBtn(i) {
  try {
    var list = MA_lineList.call(this);
    var page = parseInt(MA_getData.call(this).maPage || '0', 10);
    var idx = page * 24 + i;
    if (idx >= list.length) return '　（空）';
    var u = String(list[idx]).replace(/^https?:\/\//, '').replace(/\/+$/, '');
    var sp = this.source.get('maSp' + idx) || '';
    var cur = MA_cur.call(this).replace(/\/+$/, '') === String(list[idx]).replace(/\/+$/, '') ? '▶' : '　';
    var label = cur + (sp ? '⚡' + sp + ' ' : '') + u;
    if (label.length > 18) label = label.substring(0, 18);
    return label;
  } catch (e) { return '　线路' + i; }
}
function MA_pageLabel() {
  try {
    var d = MA_getData.call(this);
    var list = MA_lineList.call(this);
    var page = parseInt(d.maPage || '0', 10);
    return '　线路 ' + (page + 1) + '/' + Math.max(1, Math.ceil(list.length / 24));
  } catch (e) { return '　线路 1'; }
}

// 并发测速并切到最快线路，返回 {best, ms, tested}（供 fetch 后自动调用 + 手动测速按钮复用）
function MA_pickFastest() {
  var list = MA_lineList.call(this);
  if (!list.length) return null;
  var best = -1, bestMs = 999999, tested = 0, lastErr = '', mode = '';
  var i, ms, txt;
  // 通道1：ajaxAll 并发（快，2秒）；订阅源面板环境可能不可用
  var rs = null;
  try {
    var more = [];
    for (i = 0; i < list.length; i++) {
      var t0 = String(list[i]).replace(/\/cn\/?$/, '') + '/status.html?t=' + Date.now();
      more.push(t0 + ',{"headers":' + MA_hdrPanel() + ',"retry":0}');
    }
    rs = java.ajaxAll(more, true);
    var n = (rs && (rs.length || (rs.size ? rs.size() : 0))) || 0;
    // 严格预检：首个结果必须 callTime 是正数且 body 不含 Exception（防 java 失败返回堆栈串冒充成功）
    var rsOk = false;
    try {
      var ct0 = parseInt(rs[0].callTime(), 10);
      var bd0 = String(rs[0].body() || '');
      rsOk = (n >= list.length && ct0 > 0 && bd0.indexOf('Exception') < 0 && bd0.indexOf('timeout') < 0);
    } catch (eChk) { rsOk = false; }
    if (rsOk) {
      mode = 'ajaxAll';
      for (i = 0; i < n; i++) {
        ms = 999999; txt = '';
        try { ms = parseInt(rs[i].callTime(), 10) / 2.5; } catch (e) {}
        try { txt = String(rs[i].body() || ''); } catch (e2) {}
        if (txt.trim() !== 'ok' || ms > 15000 || ms < 0) ms = 999999;
        try { this.source.put('maSp' + i, ms === 999999 ? '超时' : ms.toFixed(0) + 'ms'); } catch (e9) {}
        if (ms < 15000) tested++;
        if (ms < bestMs) { bestMs = ms; best = i; }
      }
    } else { rs = null; }
  } catch (e) { lastErr = 'ajaxAll:' + String(e).substring(0, 40); rs = null; }
  // 通道2：ajaxAll 不可用 → connect 串行兜底
  if (!rs) {
    mode = 'connect';
    for (i = 0; i < list.length; i++) {
      var u = String(list[i]).replace(/\/cn\/?$/, '');
      ms = 999999; txt = '';
      try {
        var r = java.connect(u + '/status.html?t=' + Date.now(), MA_hdrPanel(), 6000);
        var ct = 0; try { ct = parseInt(r.callTime(), 10); } catch (e3) {}
        try { txt = String(r.body() || ''); } catch (e4) {}
        if (txt.trim() === 'ok' && ct >= 0) ms = ct / 2.5;
      } catch (e5) { lastErr = 'connect:' + String(e5).substring(0, 40); }
      try { this.source.put('maSp' + i, ms === 999999 ? '超时' : ms.toFixed(0) + 'ms'); } catch (e6) {}
      if (ms < 15000) tested++;
      if (ms < bestMs) { bestMs = ms; best = i; }
    }
  }
  try { this.source.put('maSpeedDiag', 'mode=' + mode + ' tested=' + tested + ' best=' + best + ' err=' + lastErr); } catch (e7) {}
  if (best >= 0 && bestMs < 15000) {
    MA_writeLine.call(this, String(list[best]).replace(/\/cn\/?$/, ''));
    return {best: best, line: String(list[best]), ms: bestMs, tested: tested};
  }
  return null;
}

// 🧭 一键从发布页获取线路（获取后自动测速选最快）
function MA_actionFetch() {
  MA_toast('🧭 正在解析发布页线路…', true);
  try {
    var pub = '';
    try { pub = String(result && result.get ? (result.get('pub') || '') : ''); } catch (e) {}
    var res = MA_fetchPub.call(this, pub);
    if (!res || !res.lines || !res.lines.length) {
      MA_toast('❌ 未解析到线路，检查网络或发布页地址', true);
      return;
    }
    MA_storeLines.call(this, res.lines);
    var d = MA_getData.call(this);
    d.maPage = '0';
    try { this.source.setVariable(JSON.stringify(d)); } catch (e) {}
    // 默认先落在导航给的线路（下面测速后会覆盖为最快）
    MA_writeLine.call(this, String(res.def || res.lines[0]).replace(/\/cn\/?$/, ''));
    MA_toast('✅ 获取 ' + res.lines.length + ' 条线路，正在测速选最快…', true);
    // 自动测速选最快
    var fast = MA_pickFastest.call(this);
    if (fast) {
      MA_toast('⚡ 已选最快：' + fast.line.replace(/^https?:\/\//, '').replace(/\/cn\/?$/, '') + ' ' + fast.ms + 'ms（' + fast.tested + '条）', true);
    } else {
      MA_toast('✅ 已获取 ' + res.lines.length + ' 条线路（自动测速失败，请手动点⏱）', true);
    }
    MA_reUi();
  } catch (e) { MA_toast('❌ 解析失败：' + String(e).substring(0, 60), true); }
}

// ⏱ 测速（并发 ajaxAll），ms 写按钮
function MA_actionTest() {
  var list = MA_lineList.call(this);
  if (!list.length) { MA_toast('⚠️ 请先点🧭获取线路', true); return; }
  MA_toast('⏱ 正在测速 ' + list.length + ' 条线路…', true);
  var fast = MA_pickFastest.call(this);
