/*
 * MissAV 正文 —— type=2 视频订阅源，必须输出【纯视频直链 URL】
 * 源码实锤 VideoPlay.startPlay()：
 *   content.trim() 若以 '<' 开头 → 当 MPD 文本写文件（我的旧 HTML 播放器就是这么坏的！）
 *   否则 → NetworkUtils.getAbsoluteURL(link, content) 当 URL 直接喂播放器
 *   player.mapHeadData = analyzeUrl.headerMap → 源 header(含Referer)传给播放器
 * 所以这里只输出 jmpres m3u8 URL，Referer 由源 header 注入，绝不能输出 HTML。
 */
(function () {
  var html = '' + (typeof result !== 'undefined' ? result : '');
  var siteBase = 'https://www.missav9.net';
  try { if (baseUrl && ('' + baseUrl).indexOf('http') === 0) { var mm = ('' + baseUrl).match(/^(https?:\/\/[^/]+)/); if (mm) siteBase = mm[1]; } } catch (e) {}

  // packer 解码：正则定位 a/c 与 k 串边界（k 串含 .split('|')，不能用通用逗号 split）
  function unpackPacked(h) {
    var s = h.indexOf('eval(function(p,a,c,k,e,d)');
    if (s < 0) return '';
    var rp = h.indexOf('return p}', s);
    if (rp < 0) return '';
    rp += 9;
    var en = h.indexOf(',0,{}))', rp);
    if (en < 0) return '';
    var call = h.substring(rp, en);
    var acm = call.match(/',(\d+),(\d+),'/);
    if (!acm) return '';
    var a = parseInt(acm[1], 10);
    var kpos = call.indexOf("'", acm.index + acm[0].length - 1);
    var kend = call.indexOf("'.split('|')", kpos);
    if (kpos < 0 || kend < 0) return '';
    var kstr = call.substring(kpos + 1, kend);
    var pstr = call.substring(2, acm.index + 1);
    var k = kstr.split('|'), d = {};
    for (var i = 0; i < k.length; i++) d[i.toString(a)] = k[i] || i.toString(a);
    return pstr.replace(/\b\w+\b/g, function (x) { return d[x] !== undefined ? d[x] : x; });
  }
  var dec = unpackPacked(html);
  var m = dec.match(/https?:\/\/([^\/'"\s]+)(\/[^\'"\s]*playlist\.m3u8)/);
  if (!m) return '';
  // 输出纯 m3u8 URL；播放器会用源 header(Referer) 注入请求。
  return siteBase + '/jmpres/' + m[1] + m[2];
})()

